find:
a = (arms or {}).get(track)
if not a:
    return init_arm(cfg)

replace:
a = (arms or {}).get(track)
if not a:
    # A track we have never pulled should not start out buried underneath the
    # arms we have already learned: seed it from the strongest posterior on the
    # board so it gets a fair chance of being drawn.
    peers = [p for p in (arms or {}).values() if isinstance(p, dict)]
    if peers:
        best = max(peers, key=posterior_mean)
        return {"alpha": float(best.get("alpha", 1.0)),
                "beta": float(best.get("beta", 1.0)), "n": 0}
    return init_arm(cfg)
